import { handle, hashSessionToken, sessionCookie, randomToken } from '../../../ctf-lib/server.js';

// One-time re-entry link generated by the admin: /api/ctf/resume?t=<token>
export const onRequestGet = handle(async ({ request, env }) => {
	const t = new URL(request.url).searchParams.get('t') || '';
	const bad = () => Response.redirect(new URL('/ctf/register?resume=invalid', request.url).toString(), 302);
	if (t.length < 20 || t.length > 100) return bad();
	const h = await hashSessionToken(env, 'resume:' + t);
	const p = await env.CTF_DB.prepare('SELECT id FROM participants WHERE session_hash = ?').bind(h).first();
	if (!p) return bad();
	const token = randomToken();
	await env.CTF_DB.prepare('UPDATE participants SET session_hash = ? WHERE id = ?').bind(await hashSessionToken(env, token), p.id).run();
	return new Response(null, { status: 302, headers: { location: '/ctf/challenge', 'set-cookie': sessionCookie(token), 'cache-control': 'no-store' } });
});
